"""Genetics, and the four things it is not allowed to do.

The programme plan names this as the live hazard: "Genetics read as diagnosis
(APOE is the live hazard) | a variant alone can never originate an insight --
only appear as context beside a measured marker". Every test here is one half
of that sentence.
"""

import pytest
import yaml

from app.analytics import genetics, variant_catalog
from app.analytics.variant_catalog import VariantCatalogError

APOE = ["rs429358", "rs7412"]


def raw_23andme(rows) -> str:
    header = (
        "# This data file generated by 23andMe at: Sun Oct 11 2026\n"
        "# rsid\tchromosome\tposition\tgenotype\n"
    )
    return header + "".join(
        f"{rsid}\t{chrom}\t{pos}\t{call}\n" for rsid, chrom, pos, call in rows
    )


# ── The catalog ──────────────────────────────────────────────────────────────

def test_the_shipped_catalog_loads():
    version, variants = variant_catalog.load_variants()
    assert version
    assert "rs1801133" in variants


def test_every_variant_names_a_marker_that_exists():
    """`context_for` is how "a variant may never originate an insight" is
    structural. A variant pointing at a marker that is not in the catalog
    could never be shown beside anything, so it would be a genotype we store
    and cannot use."""
    from app.analytics import catalog

    _, variants = variant_catalog.load_variants()
    for variant in variants.values():
        assert variant.context_for
        for biomarker_id in variant.context_for:
            assert catalog.get(biomarker_id) is not None, biomarker_id


def test_a_variant_with_no_marker_to_be_context_for_is_refused(tmp_path):
    path = tmp_path / "v.yaml"
    path.write_text(yaml.safe_dump({
        "version": "v", "refused": [], "variants": [{
            "rsid": "rs762551", "gene": "CYP1A2", "trait": "caffeine",
            "context_for": [], "note": "n", "citation": "c",
        }], "clinical_review": {"variants": []},
    }))
    variant_catalog.load_variants.cache_clear()
    with pytest.raises(VariantCatalogError, match="context"):
        variant_catalog.load_variants(path)
    variant_catalog.load_variants.cache_clear()


def test_a_variant_that_is_also_on_the_refused_list_is_refused(tmp_path):
    """The contradiction that would otherwise be resolved by dictionary
    order, which is not how a safety boundary should be decided."""
    path = tmp_path / "v.yaml"
    path.write_text(yaml.safe_dump({
        "version": "v",
        "refused": [{"rsid": "rs1801133", "gene": "MTHFR", "reason": "r"}],
        "variants": [{
            "rsid": "rs1801133", "gene": "MTHFR", "trait": "folate",
            "context_for": ["homocysteine"], "note": "n", "citation": "c",
        }],
        "clinical_review": {"variants": []},
    }))
    variant_catalog.load_variants.cache_clear()
    with pytest.raises(VariantCatalogError, match="both"):
        variant_catalog.load_variants(path)
    variant_catalog.load_variants.cache_clear()


def test_the_shipped_catalog_is_not_clinically_reviewed_yet():
    _, variants = variant_catalog.load_variants()
    assert not any(variant_catalog.review_status(r).reviewed for r in variants)


# ── APOE, by name ────────────────────────────────────────────────────────────

def test_apoe_is_named_on_the_refused_list():
    """Redundant with the allowlist, and written out so that "we do not store
    APOE" is something a test asserts rather than something you derive from
    an absence."""
    refused = variant_catalog.refused_rsids()
    assert set(APOE) <= refused


def test_apoe_is_not_on_the_allowlist():
    _, variants = variant_catalog.load_variants()
    assert not set(APOE) & set(variants)


def test_apoe_in_an_imported_file_is_discarded_and_not_merely_hidden():
    """The whole hazard in one test. Both APOE SNPs are present in the file
    and neither appears in anything the import returns."""
    text = raw_23andme([
        ("rs429358", "19", "45411941", "CT"),
        ("rs7412", "19", "45412079", "CC"),
        ("rs1801133", "1", "11856378", "TT"),
    ])

    result = genetics.import_raw(text)

    stored = {call.rsid for call in result.calls}
    assert stored == {"rs1801133"}
    assert not set(APOE) & stored
    # Nothing anywhere in the result mentions them, including the counts.
    assert "rs429358" not in repr(result)


def test_the_count_of_discarded_rows_carries_no_identities():
    """"We read 600,000 rows and kept 3" is useful to a user. Which of the
    599,997 were interesting is the thing we are refusing to say."""
    text = raw_23andme([
        ("rs429358", "19", "45411941", "CT"),
        ("rs7903146", "10", "114758349", "TT"),
        ("rs1801133", "1", "11856378", "TT"),
    ])

    result = genetics.import_raw(text)

    assert result.read == 3
    assert result.discarded == 2
    assert [call.rsid for call in result.calls] == ["rs1801133"]


# ── Parsing ──────────────────────────────────────────────────────────────────

def test_a_23andme_file_is_read():
    text = raw_23andme([("rs1801133", "1", "11856378", "CT")])

    result = genetics.import_raw(text)

    assert result.format == genetics.TWENTY_THREE_AND_ME
    assert result.calls[0].genotype == "CT"


def test_a_no_call_is_not_a_genotype():
    """23andMe writes `--` where the chip failed to read. Storing that as a
    genotype would be inventing one."""
    text = raw_23andme([
        ("rs1801133", "1", "11856378", "--"),
        ("rs855791", "22", "37462936", "AG"),
    ])

    result = genetics.import_raw(text)

    assert [call.rsid for call in result.calls] == ["rs855791"]


def test_a_vcf_is_read():
    text = (
        "##fileformat=VCFv4.2\n"
        "#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO\tFORMAT\tSAMPLE\n"
        "1\t11856378\trs1801133\tG\tA\t.\tPASS\t.\tGT\t0/1\n"
    )

    result = genetics.import_raw(text)

    assert result.format == genetics.VCF
    assert result.calls[0].rsid == "rs1801133"
    assert result.calls[0].genotype == "AG"


def test_a_vcf_homozygous_alternate_is_two_alternate_alleles():
    text = (
        "##fileformat=VCFv4.2\n"
        "#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO\tFORMAT\tSAMPLE\n"
        "1\t11856378\trs1801133\tG\tA\t.\tPASS\t.\tGT\t1|1\n"
    )

    assert genetics.import_raw(text).calls[0].genotype == "AA"


def test_a_vcf_apoe_row_is_discarded_too():
    """The allowlist is applied after parsing and before anything else, so it
    cannot be bypassed by arriving in a different file format."""
    text = (
        "##fileformat=VCFv4.2\n"
        "#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO\tFORMAT\tSAMPLE\n"
        "19\t45411941\trs429358\tT\tC\t.\tPASS\t.\tGT\t0/1\n"
    )

    assert genetics.import_raw(text).calls == ()


def test_a_vcf_with_no_genotype_call_is_skipped():
    text = (
        "##fileformat=VCFv4.2\n"
        "#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO\tFORMAT\tSAMPLE\n"
        "1\t11856378\trs1801133\tG\tA\t.\tPASS\t.\tGT\t./.\n"
    )

    assert genetics.import_raw(text).calls == ()


def test_a_file_in_no_recognised_format_is_refused_rather_than_guessed_at():
    with pytest.raises(genetics.UnreadableGeneticFile):
        genetics.import_raw("this is a photograph of a cat")


def test_an_empty_file_is_refused():
    with pytest.raises(genetics.UnreadableGeneticFile):
        genetics.import_raw("")


def test_the_same_rsid_twice_keeps_the_first_call():
    """A merged export can repeat a row. Two genotypes for one locus is a
    contradiction, and picking the later one silently would make the result
    depend on file order."""
    text = raw_23andme([
        ("rs1801133", "1", "11856378", "CT"),
        ("rs1801133", "1", "11856378", "TT"),
    ])

    result = genetics.import_raw(text)

    assert len(result.calls) == 1
    assert result.calls[0].genotype == "CT"
    assert result.conflicts == 1


# ── A variant is only ever context ───────────────────────────────────────────

def test_a_variant_is_attached_to_a_marker_the_user_actually_has():
    stored = [{"rsid": "rs1801133", "genotype": "TT"}]
    results = [{"biomarker_id": "homocysteine", "value_canonical": 14.0}]

    attached = genetics.context_for_results(stored, results)

    assert attached["homocysteine"][0]["rsid"] == "rs1801133"


def test_a_variant_with_no_matching_result_is_not_returned_at_all():
    """The structural half of "a variant may never originate an insight".
    There is no marker for it to be context for, so there is nothing to
    return -- not an empty explanation, not a standalone genotype."""
    stored = [{"rsid": "rs1801133", "genotype": "TT"}]

    assert genetics.context_for_results(stored, []) == {}


def test_a_variant_is_not_attached_to_a_marker_it_does_not_name():
    stored = [{"rsid": "rs2282679", "genotype": "GG"}]
    results = [{"biomarker_id": "ferritin", "value_canonical": 40.0}]

    assert genetics.context_for_results(stored, results) == {}


def test_an_unreviewed_note_is_withheld_but_the_genotype_is_not():
    """A genotype is a measurement of a fact about a person. What it means is
    a clinical claim and waits for a signature, exactly as a lab value's
    verdict does."""
    stored = [{"rsid": "rs1801133", "genotype": "TT"}]
    results = [{"biomarker_id": "homocysteine", "value_canonical": 14.0}]

    attached = genetics.context_for_results(stored, results)[("homocysteine")]

    assert attached[0]["genotype"] == "TT"
    assert attached[0]["note"] is None
    assert attached[0]["note_reviewed"] is False


def test_a_stored_variant_that_is_no_longer_on_the_allowlist_is_not_surfaced():
    """Defence in depth. If a variant is removed from the catalog -- because
    it turned out to carry more meaning than we thought -- rows already in
    the database must stop being shown, without needing a migration to have
    run first."""
    stored = [{"rsid": "rs429358", "genotype": "CT"}]
    results = [{"biomarker_id": "homocysteine", "value_canonical": 14.0}]

    assert genetics.context_for_results(stored, results) == {}


# ── The question a person will actually ask ──────────────────────────────────

def test_asking_for_the_alzheimers_gene_is_answered_deterministically():
    """Decided before the tool exists, as the handoff requires. A model's
    behaviour varies between two identical runs and this is the one question
    where that is not acceptable."""
    match = genetics.screen_for_genetic_risk("do I have the Alzheimer's gene?")

    assert match is not None
    assert match.matched_rule == "alzheimers"


@pytest.mark.parametrize("question", [
    "what is my APOE status",
    "am I apoe4",
    "do I carry the BRCA gene",
    "what does my genetic test say about my cancer risk",
    "am I a carrier for huntington's",
    "do my genes mean I will get dementia",
    "do I have the breast cancer gene",
])
def test_every_way_of_asking_the_same_question_is_screened(question):
    assert genetics.screen_for_genetic_risk(question) is not None


@pytest.mark.parametrize("question", [
    "what was my vitamin D last time",
    "how did I sleep last night",
    "my grandmother had dementia, is my sleep okay",
    "what is my readiness score",
])
def test_an_ordinary_question_is_not_screened(question):
    """A screen that fires on anything containing a disease word would make
    the concierge useless and train people to ignore it."""
    assert genetics.screen_for_genetic_risk(question) is None


def test_the_refusal_says_what_we_hold_and_where_to_go():
    """"I cannot help with that" sends somebody who is frightened away with
    nothing. It has to say we never read it, and who can."""
    match = genetics.screen_for_genetic_risk("do I have the Alzheimer's gene?")

    assert "never" in match.response.lower() or "do not" in match.response.lower()
    assert "counsel" in match.response.lower()


# ── There is no tool for this ────────────────────────────────────────────────

def test_no_agent_tool_can_list_a_users_variants():
    """The absence IS the enforcement, exactly as the missing
    `clinical_drafts` loader method is. A `get_variants` tool would be a
    diagnosis generator with extra steps: the model would have the genotypes
    and the guardrails would be the only thing between them and the user.
    """
    from app.agent.data_tools import build_data_tools
    from app.common.context_loader import ContextLoader
    from tests.fakes import FakeSupabase

    names = {t.name for t in build_data_tools(ContextLoader(FakeSupabase({})))}

    # Spelled out rather than matched on a substring: "epigenetic" contains
    # "gene", and a check that has to be loosened to pass is a check nobody
    # trusts afterwards. `get_epigenetic_clocks` is a different thing -- a
    # result from a provider the user paid, not a genotype.
    forbidden = {"get_variants", "get_genetics", "get_genotypes", "get_genes"}
    assert not names & forbidden
    assert not any(
        word in name for name in names for word in ("variant", "genotype", "snp")
    )


def test_the_scoped_loader_has_no_method_that_returns_variants_alone():
    """The other half: a tool cannot reach what the loader cannot read. The
    only way a genotype leaves the database is attached to a lab result."""
    from app.common.context_loader import ContextLoader

    offenders = [
        name
        for name in dir(ContextLoader)
        if not name.startswith("_")
        and ("variant" in name or name == "genetics")
    ]
    assert offenders == []
